func pageCache(ttl time.Duration, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		key := r.Method + " " + r.URL.RequestURI() + " " + r.Header.Get("Accept-Encoding")
		if e, ok := store.get(key); ok && !e.expired() {
			w.Header().Set("Cache-Control", "public, max-age=60")
			w.Write(e.body)              // handler, queries and templates skipped
			return
		}
		rec := newRecorder(w)            // buffers; does not forward while recording
		next.ServeHTTP(rec, r)
		store.put(key, rec.body(), ttl)
		rec.flushTo(w)
	})
}
